import{_ as s,o as t,c as n,a4 as e}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"多 Agent 对证循环架构通览","description":"","frontmatter":{"title":"多 Agent 对证循环架构通览","date":"2026-05-26T00:00:00.000Z"},"headers":[],"relativePath":"posts/对证循环架构通览.md","filePath":"posts/对证循环架构通览.md"}'),d={name:"posts/对证循环架构通览.md"};function i(l,a,p,o,r,h){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="多-agent-对证循环架构通览" tabindex="-1">多 Agent 对证循环架构通览 <a class="header-anchor" href="#多-agent-对证循环架构通览" aria-label="Permalink to &quot;多 Agent 对证循环架构通览&quot;">​</a></h1><blockquote><p>Hermes / CC (Claude Code) / Codex CLI 三 Agent 协作框架 2026-05-26 ~ 2026-06-12 · project-archive</p></blockquote><hr><h2 id="一、架构概览" tabindex="-1">一、架构概览 <a class="header-anchor" href="#一、架构概览" aria-label="Permalink to &quot;一、架构概览&quot;">​</a></h2><p><strong>对证循环（Concordance Loop）</strong> 是一种 peer-review 式的多 Agent 协作模式。三个角色各司其职：</p><table tabindex="0"><thead><tr><th>角色</th><th>工具</th><th>职责</th><th>运行模式</th></tr></thead><tbody><tr><td>Hermes</td><td>Hermes Agent</td><td>大脑：规划、调度、终审、归档</td><td>常驻终端，交互式</td></tr><tr><td>CC</td><td>Claude Code CLI</td><td>手：发散型编码、实现</td><td>持久窗口，事件驱动</td></tr><tr><td>Codex</td><td>Codex CLI</td><td>眼：严谨审查、找问题</td><td>持久窗口，事件驱动</td></tr></tbody></table><p>核心原则：<strong>事件驱动，不定时不轮询，不废 token。</strong></p><hr><h2 id="二、对证循环流程" tabindex="-1">二、对证循环流程 <a class="header-anchor" href="#二、对证循环流程" aria-label="Permalink to &quot;二、对证循环流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Hermes 规划任务 → 创建 STATUS.md → 启动工作间</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>CC 读 STATUS.md → 实现 → git commit → notify</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Codex 被唤醒 → 读 STATUS.md + git diff → 审查</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ├─ REVIEW-PASS → 通知 Hermes → 终审 → 归档</span></span>
<span class="line"><span>    └─ REVIEW-FAIL → 通知 CC → 修复 → 再循环</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>  循环，直到 REVIEW-PASS 或超限 5 轮</span></span></code></pre></div><h3 id="关键设计" tabindex="-1">关键设计 <a class="header-anchor" href="#关键设计" aria-label="Permalink to &quot;关键设计&quot;">​</a></h3><ol><li><strong>STATUS.md 是唯一的交流通道</strong> — 不接受 Agent 之间直接通信</li><li><strong>git 是事件容器</strong> — commit 触发通知，但不承载协议</li><li><strong>notify-agent.sh 是门铃</strong> — 一行 curl POST 到路由层，不带上下文</li><li><strong>路由层做决策</strong> — 解析 commit 作者 or 消息前缀，决定唤醒哪一方</li></ol><h3 id="迭代记录" tabindex="-1">迭代记录 <a class="header-anchor" href="#迭代记录" aria-label="Permalink to &quot;迭代记录&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>| 轮次 | 提交者 | 结果 | 详情                        |</span></span>
<span class="line"><span>|------|--------|------|-----------------------------|</span></span>
<span class="line"><span>| 1    | CC     | 完成 | 实现 JWT 登录签发           |</span></span>
<span class="line"><span>| 2    | Codex  | REVIEW-FAIL | token 过期校验缺失    |</span></span>
<span class="line"><span>| 3    | CC     | 修复 | 增加 exp 字段检查            |</span></span>
<span class="line"><span>| 4    | Codex  | REVIEW-PASS | 审查通过               |</span></span></code></pre></div><hr><h2 id="三、三层架构" tabindex="-1">三、三层架构 <a class="header-anchor" href="#三、三层架构" aria-label="Permalink to &quot;三、三层架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│          路由层（n8n）                │</span></span>
<span class="line"><span>│  事件接收 → 解析 → 决策 → 注入       │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│          会话层（持久窗口）            │</span></span>
<span class="line"><span>│  Agent 常驻 → send-keys 注入 → 读输出 │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│          协议层（文件级）              │</span></span>
<span class="line"><span>│  STATUS.md + SKILL.md                │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层</th><th>职责</th><th>可替换为</th></tr></thead><tbody><tr><td>路由层</td><td>Webhook 接收、commit 解析、决策、注入</td><td>n8n / Dify / LangGraph / 自建脚本</td></tr><tr><td>会话层</td><td>Agent 持久化、命令注入、输出读取</td><td>Windows 终端 / WSL tmux / Docker</td></tr><tr><td>协议层</td><td>共享状态格式、Agent 行为规范</td><td>STATUS.md + SKILL.md</td></tr></tbody></table><p>核心思想：<strong>每一层都是可替换的协议接口，不是框架绑定。</strong></p><hr><h2 id="四、工作间模型" tabindex="-1">四、工作间模型 <a class="header-anchor" href="#四、工作间模型" aria-label="Permalink to &quot;四、工作间模型&quot;">​</a></h2><ul><li><strong>工作间（Workspace）</strong> = 一个任务 + 一对 CC/Codex + 一个 STATUS.md</li><li>工作间之间可并发</li><li>工作间 STATUS.md 放在 <code>workspaces/wsXXX/STATUS.md</code></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>D:/files/HomeSense/</span></span>
<span class="line"><span>  STATUS.md              ← 项目级状态（Hermes 维护）</span></span>
<span class="line"><span>  workspaces/</span></span>
<span class="line"><span>    ws001-jwt-auth/</span></span>
<span class="line"><span>      STATUS.md          ← 工作间状态（CC/Codex 对话）</span></span>
<span class="line"><span>      events/             ← 事件文件</span></span></code></pre></div><hr><h2 id="五、与现有方案的核心差异" tabindex="-1">五、与现有方案的核心差异 <a class="header-anchor" href="#五、与现有方案的核心差异" aria-label="Permalink to &quot;五、与现有方案的核心差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统方案</th><th>本架构</th></tr></thead><tbody><tr><td>通信</td><td>LangGraph 图内传消息</td><td>STATUS.md 文件协议</td></tr><tr><td>注入</td><td>插件/子进程</td><td>原生窗口 send-keys</td></tr><tr><td>持久性</td><td>干完就消亡</td><td>窗口常驻，会话连续</td></tr><tr><td>并发</td><td>单线程</td><td>多工作间并行</td></tr><tr><td>耦合度</td><td>框架锁死</td><td>三层可替换</td></tr><tr><td>可调试</td><td>黑箱</td><td>文件即日志，人可读</td></tr></tbody></table><hr><h2 id="六、核心原则" tabindex="-1">六、核心原则 <a class="header-anchor" href="#六、核心原则" aria-label="Permalink to &quot;六、核心原则&quot;">​</a></h2><ol><li><strong>文档是主权，Agent 是工具</strong> — STATUS.md 是唯一的真实源</li><li><strong>事件驱动，拒绝轮询</strong> — 不做 sleep 循环，commit 触发一切</li><li><strong>协议不绑项目配置</strong> — Hook 只做 curl，路由在 n8n，Agent 行为在 SKILL.md</li><li><strong>系统可手动修改</strong> — 所有文件都是人可读可改的，不依赖 Agent</li></ol>`,29)])])}const b=s(d,[["render",i]]);export{g as __pageData,b as default};
